
tex_add = r"""% ============================================================
% AH3: Ahmed's Problem 3 at every angle -- paragraph + theorem
% generated by step files in research/08_theory/AH3_fn_any_angle/
% ============================================================

\paragraph{Ahmed's Problem 3 at every angle}
Combine Sections~\ref{sec:corners} and~\ref{sec:fn}. For the curve
$\gamma_n(x)=x\,u+f(x)^n\,v$ with turning angle $\theta$ and
$c=\cos\theta$, the length lost is again an average over a random slope,
but the slope law tilts with the angle: writing $m_y(s)=|\{y'>s\}|$ for
$y=f^n$,
\[
2-L_n=\int_0^1 h_c(y'(x))\,dx=\int_0^\infty\phi_\theta(s)\,m_y(s)\,ds
=(1-\cos\theta)\,\mathbb E[m_y(S_\theta)],
\]
where $\phi_\theta(s)=h_c'(s)=1-(s+c)/\sqrt{1+2cs+s^2}$ has mass
$1-\cos\theta$. The slope $S_\theta$ has three faces. Its tail is the
Legendre density of Section~\ref{sec:corners}-A,
$\mathbb P(S_\theta>s)=(\sqrt{1+2cs+s^2}-s-c)/(1-c)$; explicitly
$S_\theta=\cos^2\frac\theta2\,U^{-1}-\cos\theta-\sin^2\frac\theta2\,U$
with $U$ uniform on $(0,1)$ --- equivalently $S_\theta=\sin(\theta-B)/\sin B$
with $\tan(B/2)$ uniform on $(0,\tan\frac\theta2)$, where $B$ is the angle
the chord $u+s v$ makes with $v$; and its Mellin transform is the Legendre
integral of Theorem~\ref{thm:P2},
\[
\mathbb E[S_\theta^w]=\frac{\pi w}{\sin\pi w}\,
\frac{\Lambda_w(\theta)}{1-\cos\theta},\qquad -1<w<1,
\]
so $\log\mathbb E[S_\theta^w]=\sum_{j\ge1}a_jw^j$: the coefficients
$a_j$ of Theorem~\ref{thm:P2asym} \emph{are} the cumulants of $\log
S_\theta$, and the cumulants of $\log(1/S_\theta)$ are $k_j=(-1)^jj!\,a_j$.
The geometric mean slope is $e^{a_1}=(\cos^2\frac\theta2)^{-\cot^2\frac\theta2}/e$,
which is the $2/e$ law at $\theta=\pi/2$. The whole expansion of
Section~\ref{sec:fn} now travels to every angle, and $\zeta(3)$ enters
$\mathcal J_3$ through $k_3(\theta)=2+2\cot^6\frac\theta2\log^3\cos^2\frac\theta2
-12\cot^2\frac\theta2\,S_{1,2}(\sin^2\frac\theta2)$ --- the same Nielsen
value as the power-law corner's $a_3$, at every angle. When $f$ touches $1$
with higher contact, $-\log f(1-\tau)\sim\beta\tau^m$, the deficit changes
regime to $2-L_n\sim(1-\cos\theta)\bigl(\log n/(m\beta n)\bigr)^{1/m}$: the
angle enters only through the plateau height $1-\cos\theta$ of $h_c$.

\begin{theorem}[Length of $x u+f(x)^n v$ at every angle]\label{thm:fnangle}
Let $u,v$ be unit vectors with $u\cdot v=\cos\theta$, $0<\theta<\pi$, and
let $f$ be as in Theorem~\ref{thm:fn}. Write $z=\sin^2\frac\theta2$,
$c=\cos\theta$, $a=f'(1)$, $A=f''(1)$, $B=f'''(1)$, $\varepsilon=1/(n-1)$
and $\Xi=\log(n a)+k_1(\theta)$, with
$k_1(\theta)=1+\cot^2\frac\theta2\log\cos^2\frac\theta2$,
$k_2(\theta)=1+\frac{\pi^2}{3}-2\Li_2(z)-\cot^4\frac\theta2\log^2\cos^2\frac\theta2$,
$k_3(\theta)$ as above, and $\mu_1=\Xi$, $\mu_2=\Xi^2+k_2$,
$\mu_3=\Xi^3+3k_2\Xi+k_3$. Then
\[
2-L_n=\varepsilon\mathcal J_1+\varepsilon^2\mathcal J_2+\varepsilon^3\mathcal J_3
+O\bigl(\varepsilon^4\log^4n\bigr),
\]
where $\mathcal J_1=\frac{2z}{a}\,\mu_1$,
\[
\mathcal J_2=\frac{z}{a^3}\Bigl[A(\mu_2-2\mu_1)-a^2\mu_2+2a(1-z)\Bigr],
\]
\[
\mathcal J_3=\frac{z}{3a^5}\Bigl[a^4\mu_3-(3Aa^2+Ba)(\mu_3-3\mu_2)
+3A^2(\mu_3-4\mu_2+2\mu_1)\Bigr]-\frac{4Az(1-z)}{a^4}-\frac{cz(1-z)}{a^3}.
\]
In particular
$2-L_n\sim(1-\cos\theta)\bigl(\log n+\log f'(1)+k_1(\theta)\bigr)/(f'(1)\,n)$,
recovering Theorem~\ref{thm:fn} at $\theta=\pi/2$ and Theorem~\ref{thm:P2asym}
at $f(x)=x$.
\end{theorem}
"""
open('paper_addition.tex','w').write(tex_add)
print(tex_add[:400], '...')
print('written', len(tex_add), 'chars')
